patch.value:
if get_SC_problematic(PC) and get_LPTOTAL() > 0:
    entry_idx = -1
    tag_val = PC & ((1 << tag_bits) - 1)
    for i in range(num_entries):
        if WPT[i].tag == tag_val:
            entry_idx = i
            break

    if entry_idx != -1:
        WPT[entry_idx].ranking = min(WPT[entry_idx].ranking + 1, (1 << rank_bits) - 1)
        WPT[entry_idx].length = get_LPTOTAL() & ((1 << length_bits) - 1)
    else:
        min_rank = (1 << rank_bits)
        replace_idx = 0
        for i in range(num_entries):
            if WPT[i].ranking < min_rank:
                min_rank = WPT[i].ranking
                replace_idx = i

        WPT[replace_idx].tag = tag_val
        WPT[replace_idx].conf = 0
        WPT[replace_idx].ranking = 0
        WPT[replace_idx].length = get_LPTOTAL() & ((1 << length_bits) - 1)
        WPT[replace_idx].history = 0
        for i in range(num_counters):
            WPT[replace_idx].counters[i] = 0

meta_idx = rob_index % max_in_flight_branches
meta = WPT_InFlight_Meta[meta_idx]
if not meta.valid or meta.entry_idx == -1:
    return

entry = WPT[meta.entry_idx]

if meta.wpt_pred is not None and meta.tage_pred is not None:
    if meta.wpt_pred != meta.tage_pred:
        if meta.wpt_pred == outcome:
            entry.conf = min(entry.conf + 1, (1 << conf_bits) - 1)
        else:
            entry.conf = max(entry.conf - 1, 0)

if meta.old_history is not None and entry.length is not None:
    old_hist = meta.old_history
    h0 = old_hist & 1
    hl = (old_hist >> min(entry.length, history_bits - 1)) & 1
    hl1 = (old_hist >> min(max(entry.length - 1, 0), history_bits - 1)) & 1
    hl2 = (old_hist >> min(max(entry.length - 2, 0), history_bits - 1)) & 1
    idx = (h0 << 3) | (hl << 2) | (hl1 << 1) | hl2

    sat_value = entry.counters[idx]
    if outcome == 1:
        entry.counters[idx] = min(sat_value + 1, (1 << (counter_bits - 1)) - 1)
    else:
        entry.counters[idx] = max(sat_value - 1, -(1 << (counter_bits - 1)))

meta.valid = 0
